import { Component, ElementRef, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { FormControl, FormGroup, Validators } from '@angular/forms';
import { StockService } from '../stock.service';
import { Subscription } from 'rxjs';
import { Products } from 'src/app/core/interfaces/stock.interface';
import { ConfirmationService } from 'primeng/api';
import { Table } from 'primeng/table';

@Component({
    selector: 'category-items',
    templateUrl: './category-items.component.html',
    styleUrls: ['./category-items.component.scss']
})
export class CategoryItemsComponent implements OnInit, OnDestroy {
    @ViewChild(Table) dt: Table;

    @ViewChild('barcodeInput') barcodeInput: ElementRef;

    constructor(private stockService: StockService, private confirmationService: ConfirmationService) { }

    subscriptions = new Subscription();


    stockOptions = [{
        name: 'Yes',
        value: 1
    }, {
        name: 'No',
        value: 0
    }]

    itemDialogVisible: boolean;
    categories;
    selectedCategory;
    selectedItem;
    dialogMode: string;

    itemsSub: Subscription;
    filteredItems: Products[];

    submitted: boolean = false;

    barcodeError: boolean = false;

    ngOnInit(): void {
        this.stockService.itemDialogVisible.next(false)

        this.subscriptions.add(this.stockService.categories.subscribe(res => {
            this.categories = res;

        }))
        this.subscriptions.add(this.stockService.selectedCategory.subscribe(res => {
            this.selectedCategory = res;

        }))
        this.subscriptions.add(this.stockService.filteredItems.subscribe(res => {
            this.filteredItems = res;
            if(this.dt) {
                this.dt.reset()
            }
        }))

        this.subscriptions.add(this.stockService.selectedItem.subscribe(res => {
            this.selectedItem = res;
        }))
        this.subscriptions.add(this.stockService.itemDialogVisible.subscribe(res => {
            this.itemDialogVisible = res;
        }))
        this.subscriptions.add(this.stockService.barcodeError.subscribe(() => {
            this.barcodeInput.nativeElement.select()
            this.barcodeError = true;
        }))
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    selectItem() {
        this.stockService.selectItem(this.selectedItem);
    }

    reset() {
        this.dt.reset()
    }
    // Item form and events
    itemForm = new FormGroup({
        item_ID: new FormControl(null),
        item_description: new FormControl(null, Validators.required),
        category_ID_FK: new FormControl({ value: null, disabled: false }, Validators.required),
        has_barcode: new FormControl<string>('yes'),
        barcode: new FormControl<string | null>(null),
        currency: new FormControl('dollar', Validators.required),
        item_cost: new FormControl(null, Validators.required),
        item_price: new FormControl(null, Validators.required),
        stock_management: new FormControl<number>(1),
        qty: new FormControl<number>(null),
        item_notes: new FormControl(null)
    })
    get item_description() {
        return this.itemForm.get('item_description');
    }
    get item_cost() {
        return this.itemForm.get('item_cost');
    }
    get item_price() {
        return this.itemForm.get('item_price');
    }
    get qty() {
        return this.itemForm.get('qty')
    }




    // open category dialog
    openItemDialog(mode: string) {
        this.dialogMode = mode;
        this.barcodeError = false;
        if (this.dialogMode == 'add') {
            this.itemForm.patchValue({
                category_ID_FK: this.selectedCategory.category_ID
            })
            this.stockService.itemDialogVisible.next(true)
        } else if (this.dialogMode == 'edit') {
            if(this.selectedItem.barcode) {
                this.itemForm.patchValue({has_barcode: 'yes'})
            } else {
                this.itemForm.patchValue({has_barcode: 'no'})
            }
            this.itemForm.patchValue(
                this.selectedItem
            )
            this.stockService.itemDialogVisible.next(true)

        }
    }

    // submit category dialog
    async submitItem() {
        this.submitted = true;

        // add or remove qty required validator
        if (this.itemForm.value.stock_management == 1) {
            this.itemForm.controls['qty'].addValidators([Validators.required]);
        } else {
            this.itemForm.controls['qty'].removeValidators([Validators.required])
        }
        this.itemForm.controls['qty'].updateValueAndValidity();

        if (this.dialogMode == 'add') {
            if (this.itemForm.valid) {
                await this.stockService.createItem(this.itemForm.value)
            }
        } else {
            if (this.itemForm.valid) {
                await this.stockService.updateItem(this.itemForm.value)
                this.stockService.selectedItem.next(0)
            }
        }
    }

    // delete item
    deleteSelectedItem() {
        this.confirmationService.confirm({
            key: 'deleteItem',
            message: `Are you sure that you want to delete "${this.selectedItem.item_description}"?`,
            header: 'Warning',
            icon: 'pi pi-exclamation-triangle',
            acceptButtonStyleClass: 'p-button-danger',
            rejectButtonStyleClass: 'p-button-secondary',
            defaultFocus: 'reject',
            accept: () => {
                this.stockService.deleteItem(this.selectedItem)
                this.stockService.selectedItem.next(0)
            }
        })
    }

    // reset form dialog
    resetDialog() {
        this.submitted = false;
        this.itemForm.reset({
            has_barcode: 'yes',
            currency: 'dollar',
            stock_management: 1
        })
    }

    // clear barcode input
    clearBarcode() {
        this.itemForm.patchValue({
            barcode: null
        })
    }

    clearBarcodeError() {
        this.barcodeError = false;
    }

    clearQty() {

    }

}
