import { Component, inject } from '@angular/core';
import { StockService } from '../stock.service';

@Component({
    selector: 'app-stock-archive',
    templateUrl: './stock-archive.component.html',
    styleUrl: './stock-archive.component.scss',
})
export class StockArchiveComponent {
    readonly stockService = inject(StockService);

    startDate = this.stockService.startDate;
    endDate = this.stockService.endDate;

    archiveLoading = this.stockService.archiveLoading;

    productArchive = this.stockService.productArchive;

    startDateChanged() {
        this.refreshArchive();
    }

    endDateChanged() {
        this.refreshArchive();
    }

    refreshArchive() {
        this.stockService.fetchArchive();
    }
}
