import { Component, EventEmitter, inject, Input, Output } from '@angular/core';
import { DialogModule } from 'primeng/dialog';
import { ButtonModule } from 'primeng/button';
import { TableModule } from 'primeng/table';
import { TagModule } from 'primeng/tag';
import { StockService } from 'src/app/stock/stock.service';

@Component({
    selector: 'stock-transactions',
    standalone: true,
    imports: [DialogModule, ButtonModule, TableModule, TagModule],
    templateUrl: './stock-transactions.component.html',
    styleUrl: './stock-transactions.component.scss',
})
export class StockTransactionsComponent {
    @Input() product_id?: number;
    @Input() visible: boolean = false;
    @Output() onClose: EventEmitter<any> = new EventEmitter();

    readonly stockService = inject(StockService);

    stockHistory = this.stockService.stockHistory;

    closeDialog() {
        this.visible = false;
        this.onClose.emit();
    }

    fetchProductHistory() {
        this.stockService.fetchStockHistory(this.product_id!);
    }

    // get severity
    getSeverity(description: string): any {
        switch (description) {
            case 'SALE':
                return 'primary';

            case 'SUPPLY':
                return 'success';

            case 'RETURN':
                return 'warning';

            case 'DELETE':
                return 'danger';

            case 'DISPOSE':
                return 'danger';

            case 'ADD':
                return 'contrast';

            case 'REMOVE':
                return 'danger';

            default:
                return 'contrast';
        }
    }
}
