import { Component, effect, inject, OnInit } from '@angular/core';
import { StockService } from '../../stock.service';
import { FormBuilder } from '@angular/forms';

@Component({
    selector: 'delivery-charge',
    templateUrl: './delivery-charge.component.html',
    styleUrl: './delivery-charge.component.scss',
})
export class DeliveryChargeComponent {
    readonly stockService = inject(StockService);
    readonly fb = inject(FormBuilder);

    deliveryChargeForm;

    constructor() {
        effect(() => {
            let deliveryCharge = this.deliveryChargeValue();
            if (deliveryCharge) {
                this.deliveryChargeForm = this.fb.group({
                    setting_value: [deliveryCharge],
                });
            }
        });
    }

    deliveryChargeValue = this.stockService.deliveryChargeValue;
    deliveryChargeDialogVisible = this.stockService.deliveryChargeDialogVisible;
    updateDeliveryLoading = this.stockService.updateDeliveryLoading;

    // open dialog method
    toggleDialog(state: boolean) {
        this.stockService.deliveryChargeDialogVisible.set(state);
    }

    // submit form
    submit() {
        if (this.deliveryChargeForm.valid) {
            this.stockService.updateDeliveryCharge(
                this.deliveryChargeForm.value
            );
        }
    }

    // reset dialog method
    resetDialog() {
        this.deliveryChargeForm.reset({
            setting_value: this.deliveryChargeValue(),
        });
        this.stockService.deliveryChargeDialogVisible.set(false);
    }
}
