import { Component, OnDestroy, OnInit } from '@angular/core';
import { StockService } from '../../stock.service';
import { Subscription } from 'rxjs';
import { ExchangeRate } from 'src/app/core/interfaces/rates.interface';

@Component({
    selector: 'rate-history',
    templateUrl: './rate-history.component.html',
    styleUrl: './rate-history.component.scss'
})
export class RateHistoryComponent implements OnInit, OnDestroy {

    constructor(private stockService: StockService) { }

    subscriptions = new Subscription();
    recentRates: ExchangeRate[];

    ngOnInit(): void {
        this.subscriptions.add(this.stockService.recentRates.subscribe(res => {
            this.recentRates = res;
        }))
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

}
