import {
    Component,
    OnInit,
    OnDestroy,
    ViewChild,
    ElementRef,
    HostListener,
    inject,
} from '@angular/core';
import { FormBuilder, Validators } from '@angular/forms';
import {
    Categories,
    Products,
    Units,
} from 'src/app/core/interfaces/stock.interface';
import { Subscription } from 'rxjs';
import { StockService } from '../stock.service';
import { ConfirmationService } from 'primeng/api';
import { Table } from 'primeng/table';
import { AuxiliaryAccount } from 'src/app/core/interfaces/accounts.interface';
import { AuxiliaryService } from 'src/app/accounting/auxiliary.service';
import { PrintService } from 'src/app/print.service';
import { DateService } from 'src/app/_services/date.service';

@Component({
    selector: 'app-items',
    templateUrl: './items.component.html',
    styleUrls: ['./items.component.scss'],
})
export class ItemsComponent implements OnInit, OnDestroy {
    @ViewChild(Table) dt2: Table;
    @ViewChild('tableSearch') tableSearch: ElementRef;
    // focus barcode input on keydown
    @HostListener('document:keydown', ['$event'])
    onKeyDown(ev: KeyboardEvent) {
        if (!this.itemDialogVisible && !this.stockDialogVisible) {
            this.tableSearch.nativeElement.focus();
        }
    }

    units: Units[];
    categories: Categories[];
    items: Products[];
    selectedItem;
    dialogMode: string;
    itemDialogVisible;
    stockDialogVisible;
    submitted: boolean = false;
    suppliers: AuxiliaryAccount[];

    itemsLoading = this.stockService.itemsLoading;

    subscriptions = new Subscription();

    constructor(
        private stockService: StockService,
        private confirmationService: ConfirmationService,
        private formBuilder: FormBuilder,
        private auxiliaryService: AuxiliaryService,
        private printService: PrintService,
    ) {}

    readonly dateService = inject(DateService);

    ngOnInit(): void {
        this.subscriptions.add(
            this.stockService.units.subscribe((res) => {
                this.units = res;
            }),
        );
        this.subscriptions.add(
            this.stockService.categories.subscribe((res) => {
                this.categories = res;
            }),
        );
        this.subscriptions.add(
            this.stockService.items.subscribe((res) => {
                this.items = res;
            }),
        );
        this.subscriptions.add(
            this.stockService.itemDialogVisible.subscribe((res) => {
                this.itemDialogVisible = res;
            }),
        );
        this.subscriptions.add(
            this.stockService.stockDialogVisible.subscribe((res) => {
                this.stockDialogVisible = res;
            }),
        );
        this.subscriptions.add(
            this.auxiliaryService.suppliers.subscribe((res) => {
                this.suppliers = res;
            }),
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // Item form and events
    itemForm = this.formBuilder.group({
        product_id: [null],
        category_id_fk: [{ value: null, disabled: false }, Validators.required],
        supplier_id_fk: [{ value: null, disabled: false }, Validators.required],
        product_name: [null, Validators.required],
        sku: [null],
        barcode: [null],
        unit_id_fk: [{ value: 1, disabled: false }, Validators.required],
        quantity_per_unit: [null, Validators.required],
        unit_price_usd: [null, Validators.required],
        ttc_price: [null, Validators.required],
        product_notes: [null],
        average_cost_usd: [null, Validators.required],
    });

    get f() {
        return this.itemForm.controls;
    }

    get product_name() {
        return this.itemForm.get('product_name');
    }
    get category_id_fk() {
        return this.itemForm.get('category_id_fk');
    }
    get supplier_id_fk() {
        return this.itemForm.get('supplier_id_fk');
    }
    get unit_id_fk() {
        return this.itemForm.get('unit_id_fk');
    }
    get quantity_per_unit() {
        return this.itemForm.get('quantity_per_unit');
    }
    get unit_price_usd() {
        return this.itemForm.get('unit_price_usd');
    }
    get ttc_price() {
        return this.itemForm.get('ttc_price');
    }

    // open category dialog
    openItemDialog(mode: string) {
        this.dialogMode = mode;
        if (this.dialogMode == 'add') {
            this.stockService.itemDialogVisible.next(true);
        } else if (this.dialogMode == 'edit') {
            this.itemForm.patchValue(this.selectedItem);
            this.stockService.itemDialogVisible.next(true);
        }
    }

    toggleItemDialog() {
        this.stockService.itemDialogVisible.next(false);
    }

    // submit category dialog
    async submitItem() {
        this.submitted = true;
        if (this.dialogMode == 'add') {
            if (this.itemForm.valid) {
                await this.stockService.createItem(this.itemForm.value);
            }
        } else {
            if (this.itemForm.valid) {
                await this.stockService.updateItem(this.itemForm.value);
                this.selectedItem = null;
            }
        }
    }

    // reset form dialog
    resetDialog() {
        this.submitted = false;
        this.itemForm.reset({
            unit_id_fk: 1,
        });
        this.stockService.itemDialogVisible.next(false);
    }

    // delete item
    deleteSelectedItem() {
        this.confirmationService.confirm({
            key: 'deleteItem',
            message: `Are you sure that you want to delete "${this.selectedItem.item_description}"?`,
            header: 'Warning',
            icon: 'pi pi-exclamation-triangle',
            acceptButtonStyleClass: 'p-button-danger',
            rejectButtonStyleClass: 'p-button-secondary',
            defaultFocus: 'reject',
            accept: () => {
                this.stockService.deleteItem(this.selectedItem);
                this.selectedItem = null;
            },
        });
    }

    // clear barcode input
    clearBarcode() {
        this.itemForm.patchValue({
            barcode: null,
        });
    }

    resetTable() {
        this.selectedItem = null;
        this.dt2.reset();
        this.dt2.sortField = 'item_ID';
        this.dt2.sortOrder = 1;
        this.dt2.sortSingle();
        this.stockService.getItems();
    }

    // print stock
    printStock() {
        this.printService.printStock(this.items);
    }

    // ******************************************* CORRECT STOCK DIALOG ******************************************

    transactionOptions = [
        {
            name: 'Add',
            value: 'ADD',
        },
        {
            name: 'Remove',
            value: 'REMOVE',
        },
    ];

    // Item form and events
    stockForm = this.formBuilder.group({
        product_id_fk: [null],
        transaction_type: [
            { value: null, disabled: false },
            Validators.required,
        ],
        transaction_datetime: [
            this.dateService.getCurrentDate(),
            Validators.required,
        ],
        quantity: [null, Validators.required],
        transaction_notes: [null, Validators.required],
    });

    get transaction_type() {
        return this.stockForm.get('transaction_type');
    }
    get quantity() {
        return this.stockForm.get('quantity');
    }
    get transaction_notes() {
        return this.stockForm.get('transaction_notes');
    }

    // open category dialog
    openStockDialog() {
        this.stockService.stockDialogVisible.next(true);
    }

    toggleStockDialog() {
        this.stockService.stockDialogVisible.next(false);
    }

    // submitStock
    submitStock() {
        this.submitted = true;
        if (this.stockForm.valid) {
            this.stockForm.patchValue({
                product_id_fk: this.selectedItem.product_id,
                transaction_datetime: this.dateService.formatDate(
                    this.stockForm.controls['transaction_datetime'].value,
                    'YYYY-MM-DD',
                ),
            });
            this.stockService.submitStock(this.stockForm.value);
        }
    }

    // resetStockDialog
    resetStockDialog() {
        this.submitted = false;
        this.stockForm.reset({
            transaction_datetime: this.dateService.getCurrentDate(),
        });
        this.stockService.stockDialogVisible.next(false);
    }

    // &&&&&&&&&&&&&&&&&&& STOCK HISTORY DIALOG &&&&&&&&&&&&&&&&&&&&&&&

    fetchHistory() {
        this.stockService.fetchStockHistory(this.selectedItem!.product_id);
    }

    closeHistoryDialog() {
        this.stockService.historyDialogVisible.set(false);
    }
    historyDialogVisible = this.stockService.historyDialogVisible;

    historyLoading = this.stockService.historyLoading;
}
