import { NgModule } from '@angular/core';
import { RouterModule, Routes } from '@angular/router';
import { ItemsComponent } from './items/items.component';
import { CategoriesComponent } from './categories/categories.component';
import { StockHomeComponent } from './stock-home/stock-home.component';
import { StockSettingsComponent } from './stock-settings/stock-settings.component';
import { StockArchiveComponent } from './stock-archive/stock-archive.component';

const routes: Routes = [
    {
        path: '',
        component: StockHomeComponent,
        children: [
            {
                path: 'categories',
                data: {
                    breadcrumb: 'Categories',
                },
                component: CategoriesComponent,
            },
            {
                path: 'items',
                data: {
                    breadcrumb: 'Inventory',
                },
                component: ItemsComponent,
            },
            {
                path: 'settings',
                data: {
                    breadcrumb: 'Settings',
                },
                component: StockSettingsComponent,
            },
            {
                path: 'archive',
                data: {
                    breadcrumb: 'Archive',
                },
                component: StockArchiveComponent,
            },
            { path: '**', redirectTo: '/stock/items' },
        ],
    },
];

@NgModule({
    imports: [RouterModule.forChild(routes)],
    exports: [RouterModule],
})
export class StockRoutingModule {}
