import { Component, OnDestroy, OnInit } from '@angular/core';
import { StockService } from '../../stock.service';
import { Subscription } from 'rxjs';
import { FormBuilder } from '@angular/forms';

@Component({
    selector: 'exchange-rate',
    templateUrl: './exchange-rate.component.html',
    styleUrl: './exchange-rate.component.scss',
})
export class ExchangeRateComponent implements OnInit, OnDestroy {
    constructor(
        private stockService: StockService,
        private formBuilder: FormBuilder
    ) {}

    subscriptions = new Subscription();
    exchangeRate?;
    rateDialogVisible: boolean;
    rateForm;

    ngOnInit(): void {
        this.subscriptions.add(
            this.stockService.exchangeRate.subscribe((res) => {
                this.exchangeRate = res;
                this.rateForm = this.formBuilder.group({
                    rate_value: [this.exchangeRate.rate_value],
                });
            })
        );
        this.subscriptions.add(
            this.stockService.rateDialogVisible.subscribe((res) => {
                this.rateDialogVisible = res;
            })
        );
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }

    // open dialog method
    toggleDialog(state: boolean) {
        this.stockService.rateDialogVisible.next(state);
    }

    // submit form
    submit() {
        if (this.rateForm.valid) {
            this.stockService.updateExchangeRate(this.rateForm.value);
        }
    }

    // reset dialog method
    resetDialog() {
        this.rateForm.reset({
            rate_value: this.exchangeRate.rate_value,
        });
        this.stockService.rateDialogVisible.next(false);
    }
}
