import { CommonModule } from '@angular/common';
import { Component, inject, signal } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { ConfirmationService } from 'primeng/api';
import { ButtonModule } from 'primeng/button';
import { CardModule } from 'primeng/card';
import { DialogModule } from 'primeng/dialog';
import { InputTextModule } from 'primeng/inputtext';
import { TableModule } from 'primeng/table';
import { finalize } from 'rxjs';
import { ApiService } from 'src/app/_services/api.service';
import { NotificationsService } from 'src/app/_services/notifications.service';
import { ConfirmDialogModule } from 'primeng/confirmdialog';
import { Link } from './links.interface';
import { LinksService } from './links.service';

@Component({
    selector: 'links-component',
    standalone: true,
    imports: [
        CommonModule,
        TableModule,
        DialogModule,
        ButtonModule,
        InputTextModule,
        CardModule,
        ReactiveFormsModule,
        ConfirmDialogModule,
    ],
    templateUrl: './links-component.component.html',
    styleUrl: './links-component.component.scss',
})
export class LinksComponentComponent {
    readonly api = inject(ApiService);
    readonly notification = inject(NotificationsService);
    readonly confirmation = inject(ConfirmationService);
    readonly fb = inject(FormBuilder);
    readonly linksService = inject(LinksService);

    constructor() {
        this.getLinks();
    }

    links = this.linksService.links;
    loadingLinks = this.linksService.loadingLinks;

    selectedLink = this.linksService.selectedLink;

    getLinks() {
        this.linksService.getLinks();
    }

    // dialog
    linkDialogVisible = signal(false);
    linkDialogMode = signal<'add' | 'edit'>('add');

    openLinkDialog(mode: 'add' | 'edit') {
        this.linkDialogMode.set(mode);
        if (mode === 'edit') {
            this.linkForm.patchValue({
                link_id: this.selectedLink()!.link_id,
                description: this.selectedLink()!.description,
            });
        }
        this.linkDialogVisible.set(true);
    }

    linkForm = this.fb.group({
        link_id: [null],
        description: ['', Validators.required],
    });

    // submit link
    submitLink() {
        if (this.linkForm.valid) {
            if (this.linkDialogMode() === 'add') {
                this.createLink();
            } else {
                this.updateLink();
            }
        }
    }

    // create link
    createLink() {
        this.api.post<Link>(`links`, this.linkForm.value).subscribe({
            next: (res) => {
                this.notification.showSuccess('Link created successfully');
                this.linkDialogVisible.set(false);
                this.linkForm.reset();
                this.getLinks();
            },
        });
    }

    // update link
    updateLink() {
        this.api
            .put<Link>(
                `links/${this.selectedLink()?.link_id}`,
                this.linkForm.value,
            )
            .subscribe({
                next: (res) => {
                    this.notification.showSuccess('Link updated successfully');
                    this.linkDialogVisible.set(false);
                    this.linkForm.reset();
                    this.getLinks();
                },
            });
    }

    // delete link
    deleteLink() {
        this.confirmation.confirm({
            key: 'links',
            message: `Are you sure that you want to delete this link?`,
            header: 'Warning',
            icon: 'pi pi-exclamation-triangle',
            acceptButtonStyleClass: 'p-button-danger',
            rejectButtonStyleClass: 'p-button-secondary',
            defaultFocus: 'reject',
            accept: () => {
                this.api
                    .delete<Link>(`links/${this.selectedLink()?.link_id}`)
                    .subscribe({
                        next: (res) => {
                            this.notification.showSuccess(
                                'Link deleted successfully',
                            );
                            this.linkDialogVisible.set(false);
                            this.linkForm.reset();
                            this.getLinks();
                        },
                    });
            },
        });
    }
}
