import { Component, OnDestroy, OnInit } from '@angular/core';
import { StockService } from '../../stock.service';
import { Subscription } from 'rxjs';
import { FormBuilder } from '@angular/forms';
import * as moment from 'moment';

@Component({
    selector: 'rate-graph',
    templateUrl: './rate-graph.component.html',
    styleUrl: './rate-graph.component.scss'
})
export class RateGraphComponent implements OnInit, OnDestroy {

    constructor(private stockService: StockService, private formBuilder: FormBuilder) { }

    subscriptions = new Subscription();
    graphRates;
    graphYear: String | undefined;
    options;
    data;
    yearForm;

    ngOnInit(): void {
        const documentStyle = getComputedStyle(document.documentElement);
        const textColor = documentStyle.getPropertyValue('--text-color');
        const textColorSecondary = documentStyle.getPropertyValue('--text-color-secondary');
        const surfaceBorder = documentStyle.getPropertyValue('--surface-border');
        const successColor = documentStyle.getPropertyValue('--green-600');
        const secondaryColor = documentStyle.getPropertyValue('--surface-400');
        this.subscriptions.add(this.stockService.graphYear.subscribe(res => {
            this.graphYear = res;
            this.yearForm = this.formBuilder.group({
                year_picker: [this.graphYear]
            })
        }))
        this.subscriptions.add(this.stockService.graphRates.subscribe(res => {
            this.graphRates = res;
            let labels = this.graphRates.map(record => record.month)
            let minRates = this.graphRates.map(record => record.min_rate_value);
            let maxRates = this.graphRates.map(record => record.max_rate_value);

            let minRate;
            let maxRate
            if (minRates.length > 0) {
                minRate = Math.min(...minRates)
                maxRate = Math.max(...maxRates)
            }


            this.data = {
                labels: labels,
                datasets: [
                    {
                        label: 'Min Rate',
                        data: minRates,
                        backgroundColor: secondaryColor
                    },
                    {
                        label: 'Max Rate',
                        data: maxRates,
                        backgroundColor: successColor
                    }
                ]
            }

            this.options = {
                // indexAxis: 'y',
                maintainAspectRatio: false,
                aspectRatio: 0.73,
                plugins: {
                    legend: {
                        labels: {
                            color: textColor
                        }
                    }
                },
                scales: {
                    x: {
                        ticks: {
                            color: textColorSecondary,
                            font: {
                                weight: 500
                            }
                        },
                        grid: {
                            color: surfaceBorder,
                            drawBorder: false
                        }
                    },
                    y: {
                        min: minRate - 1000,
                        max: maxRate + 500,
                        ticks: {
                            color: textColorSecondary,
                            stepSize: 100
                        },
                        grid: {
                            color: surfaceBorder,
                            drawBorder: false
                        }
                    }

                }
            }
        }))
    }

    ngOnDestroy(): void {
        this.subscriptions.unsubscribe();
    }


    changeYear() {
        let year = moment(this.yearForm.value.year_picker).format('yyyy')
        this.stockService.graphYear.next(year)
        this.stockService.getRatesGraph(year)
    }

    setCurrentYear() {
        this.stockService.graphYear.next('2024')
        this.stockService.getRatesGraph('2024')
    }
}
